/**
 * Phase 1.23 — Season + Date carousels.
 *
 * Two independent controls that sit alongside <TimeOfDayCarousel> in
 * Section 2 of the Time Modal ("When this scene takes place"). Each is
 * a separately-pinnable field; a scene can carry any subset.
 *
 *   <SeasonRow    value={0..3 | null} onChange={(idx|null) => …} />
 *   <DateCarousel state={…} onChange={(next) => …} />
 *
 * Day-of-week is folded into <DateCarousel> as the LEAST-granular tier
 * — the writer can pin "Tuesday" alone, or layer weekday on top of any
 * more-precise tier (Month, Month + Day).
 *
 * DateCarousel state shape (mirrors the per-tier-draft / save-only-the-
 * active-tier rule from §2.2 used by <TimeOfDayCarousel>):
 *
 *   {
 *     activeTier: 'weekday' | 'month_dow' | 'month_day_dow' | null,
 *     drafts: {
 *       weekday:        { weekday: 0..6 | null },
 *       month_dow:      { weekday: 0..6 | null, monthIdx: 0..11 | null },
 *       month_day_dow:  { weekday: 0..6 | null, monthIdx: 0..11 | null, day: 1..31 | null },
 *     },
 *   }
 *
 * Cross-tier rotation carries the weekday and monthIdx forward where
 * possible; pre-fill never overwrites an existing draft.
 *
 * Storage convention (backend): SceneNode stores `weekday` (int 0..6),
 * `season` (int 0..3), `date_tier`, `date_month` (1..12),
 * `date_day_of_month` (1..31). Frontend dicts are 0-indexed for clean
 * array access; the date_month <-> array-index conversion happens at
 * the read/write boundary inside this file.
 */
import GranularityCarousel from './GranularityCarousel'
import ToggleInput from './ToggleInput'
import {
  getActiveCalendar,
  daysInMonth,
  weekdaysInDisplayOrder,
  februaryIndex,
} from '../../utils/calendarConventions'

// ── Snap-forward arrow overlay ─────────────────────────────────────
//
// Renders an SVG line from the prior pinned button to the current
// pinned button in cycle-forward direction over a grid of buttons.
// Used by the Date carousel rows to visualise the magnitude (and
// direction) of the writer's pick relative to where the chain
// currently sits on that field.
//
// Cycle semantics:
//   - Forward pick (currentIdx > priorIdx, no wrap needed):
//     single straight line from prior centre to current centre
//     with an arrowhead at the current end.
//   - Loop pick (currentIdx <= priorIdx, must wrap forward through
//     the cycle to reach current):
//     two segments — (a) prior centre to a point off the right edge
//     of the prior's row, arrowhead at the edge, and (b) a point
//     off the left edge of the current's row to current centre,
//     arrowhead at current.
//
// Geometry uses grid-cell coordinates derived from priorIdx /
// currentIdx + gridCols + totalCount. Buttons are assumed uniform
// (matches the actual CSS grid layout); the SVG uses
// preserveAspectRatio='none' so its viewBox stretches to the
// container's measured dimensions automatically — no DOM measurement
// or refs needed.
function CycleArrow({ priorIdx, currentIdx, totalCount, gridCols, accentColour }) {
  if (priorIdx == null || currentIdx == null) return null
  if (priorIdx === currentIdx) return null
  if (priorIdx < 0 || priorIdx >= totalCount) return null
  if (currentIdx < 0 || currentIdx >= totalCount) return null
  const rows = Math.max(1, Math.ceil(totalCount / gridCols))
  const stroke = accentColour || '#a78bfa'
  const arrowId = `cyc-arrow-${priorIdx}-${currentIdx}-${gridCols}-${totalCount}`
  // Convert button index → fractional grid centre in [0..100]. SVG
  // uses preserveAspectRatio='none' so these fractional coords
  // stretch to the container's pixel dimensions cleanly.
  const cellW = 100 / gridCols
  const cx = (i) => ((i % gridCols) + 0.5) * cellW
  // Build snake segments. Walk forward through cycle from priorIdx
  // to currentIdx (wrapping at totalCount). Within a single row the
  // arrow flies straight from one row-aligned point to the next; at
  // every row boundary (including the cycle wrap from last row back
  // to first) the arrow exits off the right edge and re-enters from
  // the left edge of the next row — disjoint segments connected by
  // an implicit "off-grid" jump that doesn't render.
  // Arrow runs through button centres (visually overlaid on the row).
  // For row transitions the arrow exits past the row's right edge
  // and re-enters from the next row's left edge as disjoint
  // segments — there is no implicit "across the grid" line between
  // an exit and the matching entry on a different row.
  const cellH = 100 / rows
  const rowOf = (i) => Math.floor(i / gridCols)
  const centreY = (row) => (row + 0.5) * cellH

  const segments = []
  let segStart = { x: cx(priorIdx), y: centreY(rowOf(priorIdx)) }
  let i = priorIdx
  let safety = totalCount + 1
  while (i !== currentIdx && safety-- > 0) {
    const nextI = (i + 1) % totalCount
    const iRow = rowOf(i)
    const nextRow = rowOf(nextI)
    const isCycleWrap = nextI < i
    const crossesRow = nextRow !== iRow || isCycleWrap
    if (crossesRow) {
      segments.push({ x1: segStart.x, y1: centreY(iRow), x2: 100 + cellW * 0.5, y2: centreY(iRow) })
      segStart = { x: -cellW * 0.5, y: centreY(nextRow) }
    }
    i = nextI
  }
  // Final segment ends at the current button's centre with the arrowhead.
  segments.push({
    x1: segStart.x, y1: segStart.y,
    x2: cx(currentIdx), y2: centreY(rowOf(currentIdx)),
    final: true,
  })
  return (
    <svg
      className="absolute inset-0 w-full h-full pointer-events-none"
      viewBox="0 0 100 100"
      preserveAspectRatio="none"
      style={{ overflow: 'visible' }}
    >
      <defs>
        <marker
          id={arrowId}
          viewBox="0 0 10 10"
          refX="8"
          refY="5"
          markerWidth="5"
          markerHeight="5"
          orient="auto-start-reverse"
        >
          <path d="M 0 0 L 10 5 L 0 10 z" fill={stroke} />
        </marker>
      </defs>
      {segments.map((s, idx) => (
        <line
          key={idx}
          x1={s.x1} y1={s.y1}
          x2={s.x2} y2={s.y2}
          stroke={stroke}
          strokeWidth="0.8"
          strokeDasharray="2 1.5"
          markerEnd={s.final ? `url(#${arrowId})` : undefined}
          opacity="0.85"
          vectorEffect="non-scaling-stroke"
        />
      ))}
    </svg>
  )
}

// ── Per-season accent colours ────────────────────────────────────────
//
// Spring = emerald (growth), Summer = amber (sun), Fall = orange-red
// (autumn), Winter = sky (cool / ice). Indexed by season int (0..3).
// Indices 0..3 = temperate seasons (Spring / Summer / Fall / Winter).
// Indices 4..5 = tropical seasons (Wet / Dry). Wet uses a brighter
// blue distinct from winter's lighter sky-blue; Dry uses ochre to
// avoid colliding with summer's amber.
export const SEASON_ACCENTS = ['#059669', '#f59e0b', '#c2410c', '#0ea5e9', '#3b82f6', '#d97706']

