// Glyph by index. 0..3 = temperate (Segoe-derived); 4..5 = tropical
// (custom-drawn raindrops / sun-with-cracked-ground). The Wet / Dry
// component declarations live further down in this module; function
// declarations are hoisted so referencing them here is fine.
const SEASON_GLYPHS = [SpringSeedling, SummerPalm, FallLeaves, WinterSnowflake, WetRaindrops, DrySunCracks]

// ── Tropical-climate season glyphs (DRAFT for dev preview) ────────────
//
// Wet and Dry seasons for non-temperate calendars. Bundled with the
// 4-season set so calendars that use 6 seasons (4 temperate + Wet +
// Dry) render consistently. Rendered at 32×32 viewBox so they sit
// alongside the Segoe-derived 4-season glyphs without scale drift.

// Single Segoe-derived raindrop shape (extracted from
// `Segoe UI Symbol Regular - Cloud With Rain.svg`, with the cloud
// stripped). Tip at upper-right, body widens going down-left, round
// bottom — the asymmetry already conveys a slight wind-driven slant
// before any rotation. Bounding box 0..57.5 wide, 0..84.5 tall.
const _RAINDROP_PATH = 'M57.5 0 C 53.833 12.333 51.667 25.5 51 39.5 C 50.333 55.167 49.333 65.167 48 69.5 C 44.333 79.5 36.667 84.5 25 84.5 C 8.333 84.5 0 76.167 0 59.5 C 0 34.167 19.167 14.333 57.5 0 Z'

// Three Segoe-shaped raindrops at staggered sizes — small / medium /
// large — arranged diagonally with an additional 12° rotation for the
// wind-driven slant. Scale picked so the cluster fills the 32×32
// viewBox to roughly the same "ink coverage" as the existing
// 4-season glyphs render at the same size.
export function WetRaindrops({ size, colour }) {
  return (
    <svg
      x={0} y={0}
      width={size} height={size}
      viewBox="0 0 32 32"
      preserveAspectRatio="xMidYMid meet"
    >
      <g transform="rotate(12 16 16)" fill={colour}>
        {/* Drop 1: top-left, small (height ~10). */}
        <g transform="translate(0.5 0.5) scale(0.118)">
          <path d={_RAINDROP_PATH} />
        </g>
        {/* Drop 2: middle, large focal (height ~20). */}
        <g transform="translate(8 5) scale(0.235)">
          <path d={_RAINDROP_PATH} />
        </g>
        {/* Drop 3: bottom-right, medium (height ~14). */}
        <g transform="translate(19 17) scale(0.166)">
          <path d={_RAINDROP_PATH} />
        </g>
      </g>
    </svg>
  )
}

// Sun above cracked ground. Sun = filled disc with short rays. Ground
// = horizon line with zig-zag cracks splitting downward, suggesting
// parched / drought conditions.
export function DrySunCracks({ size, colour }) {
  return (
    <svg
      x={0} y={0}
      width={size} height={size}
      viewBox="0 0 32 32"
      preserveAspectRatio="xMidYMid meet"
    >
      <g fill={colour} stroke={colour} strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round">
        {/* Sun disc */}
        <circle cx="16" cy="11" r="5" stroke="none" />
        {/* Rays radiating from the sun */}
        <line x1="16" y1="2"    x2="16"   y2="4.5" />
        <line x1="16" y1="17.5" x2="16"   y2="20"  />
        <line x1="6"  y1="11"   x2="8.5"  y2="11"  />
        <line x1="23.5" y1="11" x2="26"   y2="11"  />
        <line x1="9"  y1="4"    x2="10.7" y2="5.7" />
        <line x1="21.3" y1="16.3" x2="23" y2="18"  />
        <line x1="23" y1="4"    x2="21.3" y2="5.7" />
        <line x1="10.7" y1="16.3" x2="9"  y2="18"  />
        {/* Ground line */}
        <line x1="3" y1="25" x2="29" y2="25" strokeWidth="1.8" />
        {/* Zig-zag cracks splitting downward from the ground line.
            Each crack does 3 sharp angle changes to read as a
            crack rather than a straight leg. */}
        <path d="M9.5 25 L 11 27 L 9 28.5 L 10 30" fill="none" />
        <path d="M17 25 L 15.5 26.5 L 17.5 28.5 L 16.5 30" fill="none" />
        <path d="M23.5 25 L 25 27 L 23 28.5 L 24 30" fill="none" />
      </g>
    </svg>
  )
}

export function SeasonGlyph({ index, size = 14, colour }) {
  const Component = SEASON_GLYPHS[index]
  if (!Component) return null
  const fill = colour ?? SEASON_ACCENTS[index] ?? '#71717a'
  return <Component size={size} colour={fill} />
}

// ── Alternate set: Segoe Mahjong Tile season glyphs ──────────────────
//
// Full Segoe mahjong tile glyphs (Spring / Summer / Autumn / Winter)
