const SEASON_GLYPHS_MAHJONG = [SpringMahjong, SummerMahjong, FallMahjong, WinterMahjong]

export function SeasonGlyphMahjong({ index, size = 14, colour }) {
  const Component = SEASON_GLYPHS_MAHJONG[index]
  if (!Component) return null
  const fill = colour ?? SEASON_ACCENTS[index] ?? '#71717a'
  return <Component size={size} colour={fill} />
}

// Accent for everything weekday / month / day-of-month related — keeps
// those visually consistent and distinct from Season's per-button mix.
const DATE_ACCENT = '#0284c7' /* sky-600 */

// ── Shared button style ──────────────────────────────────────────────
//
// Matches the IntensitySlider / TimeOfDayCarousel visual language: dark
// disc resting state, accent-coloured fill + light text when active.
function PickerButton({
  label,
  active,
  onClick,
  accent = '#71717a',
  tight = false,
  fill = false,
  isPrior = false,
  priorAccent = null,
  priorTooltip = null,
}) {
  // Prior-spot indicator: when this button matches the prior POV-chain
  // scene's pinned value for the current field, render a dashed
  // accent ring OUTSIDE the button via CSS `outline` (which sits
  // outside the border and supports `dashed` natively). The button's
  // own border + active fill stay untouched. The active solid fill
  // still visually dominates when the writer also picks this button.
  const showPriorRing = isPrior && priorAccent
  return (
    <button
      type="button"
      onClick={onClick}
      className={`relative text-xs font-medium rounded-md transition-colors select-none whitespace-nowrap ${
        tight ? 'px-1.5 py-0.5' : 'px-2.5 py-1'
      } ${fill ? 'w-full' : ''} ${
        active
          ? 'text-zinc-50'
          : 'text-zinc-300 hover:text-zinc-100 hover:bg-zinc-800'
      }`}
      style={{
        backgroundColor: active ? accent : 'transparent',
        border: `1px solid ${active ? accent : '#3f3f46'}`,
        outline: showPriorRing ? `1.5px dashed ${priorAccent}` : 'none',
        outlineOffset: showPriorRing ? '2px' : 0,
      }}
      title={showPriorRing ? (priorTooltip || 'The previous scene is pinned here.') : undefined}
    >
      {label}
    </button>
  )
}

// ── Day-of-week button row (used INSIDE the Date carousel) ───────────
//
// Seven buttons (Sun .. Sat) in display order per the per-story
// `weekStart` setting. flex-nowrap so they always sit on one line —
// caller controls horizontal width via the surrounding container.
//
//   value:      int 0..6 (Sun=0 .. Sat=6) or null
//   onChange:   (newValueOrNull) => void
//   weekStart:  'sunday' (default) | 'monday'
function WeekdayRow({ value, onChange, weekStart = 'sunday', priorValue = null, priorAccent = null }) {
  const cal = getActiveCalendar()
  const order = weekdaysInDisplayOrder(weekStart)
  // Map cycle indices (0..N-1 in DISPLAY order, e.g. when weekStart
  // is 'monday' the 0th button is Monday). The arrow operates on the
  // display-order index so the wrap-around lines reflect the user's
  // weekStart preference.
  const priorDisplayIdx = priorValue == null ? null : order.indexOf(priorValue)
  const valueDisplayIdx = value == null ? null : order.indexOf(value)
  return (
    <div
      className="relative grid gap-1 w-full"
      style={{ gridTemplateColumns: `repeat(${order.length}, minmax(0, 1fr))` }}
    >
      {order.map((idx) => {
        const active = value === idx
        const isPrior = priorValue === idx
        return (
          <PickerButton
            key={idx}
            label={cal.weekdays.short[idx]}
            active={active}
            onClick={() => onChange(active ? null : idx)}
            accent={DATE_ACCENT}
            tight
            fill
            isPrior={isPrior}
            priorAccent={priorAccent}
            priorTooltip={isPrior ? `The previous scene was on ${cal.weekdays.long[idx]}.` : null}
          />
        )
      })}
      <CycleArrow
        priorIdx={priorDisplayIdx}
        currentIdx={valueDisplayIdx}
        totalCount={order.length}
        gridCols={order.length}
        accentColour={priorAccent}
      />
    </div>
  )
}

// ── Season button row (separate from Date) ───────────────────────────
//
// Four buttons (Spring / Summer / Fall / Winter), each with its own
// accent colour and Set-A glyph (seedling / palm / falling leaves /
// snowflake) stacked above the season name. Buttons are fixed size
// so the row stays uniform regardless of label length. No tier
// rotation; no cross-tier auto-fill from any other field. Click to
// pin; click the active button again to clear.
// Index where the temperate set ends and the tropical set begins.
// Used by SeasonRow to render a thin vertical divider between the
// two clusters so writers can see at a glance that the calendars
// are independent options, not a single 6-button row.
const TEMPERATE_SEASON_COUNT = 4

function SeasonButton({ name, idx, value, onChange }) {
  const active = value === idx
  const accent = SEASON_ACCENTS[idx] ?? DATE_ACCENT
  return (
    <button
      type="button"
      onClick={() => onChange(active ? null : idx)}
      className={`flex flex-col items-center justify-center gap-1 w-16 h-16 rounded-md transition-colors select-none ${
        active
          ? ''
          : 'text-zinc-300 hover:text-zinc-100 hover:bg-zinc-800'
      }`}
      style={{
        backgroundColor: active ? accent : 'transparent',
        border: `1px solid ${active ? accent : '#3f3f46'}`,
        color: active ? '#fafafa' : undefined,
      }}
    >
      <SeasonGlyph
        index={idx}
        size={32}
        colour={active ? '#fafafa' : accent}
      />
      <span className="text-[10px] font-medium leading-none">{name}</span>
    </button>
  )
}

export function SeasonRow({ value, onChange }) {
  const cal = getActiveCalendar()
  const temperate = cal.seasons.long.slice(0, TEMPERATE_SEASON_COUNT)
  const tropical  = cal.seasons.long.slice(TEMPERATE_SEASON_COUNT)
  return (
    <div className="flex flex-nowrap items-center gap-2" data-help-region="scene-time:season">
      {temperate.map((name, i) => (
        <SeasonButton key={i} name={name} idx={i} value={value} onChange={onChange} />
      ))}
      {tropical.length > 0 && (
        <>
          {/* Thin vertical divider between the temperate and
              tropical clusters so the writer reads them as two
              independent calendars rather than one 6-button row. */}
          <div className="w-px h-12 bg-zinc-700 mx-1" aria-hidden />
          {tropical.map((name, i) => (
            <SeasonButton
              key={TEMPERATE_SEASON_COUNT + i}
              name={name}
              idx={TEMPERATE_SEASON_COUNT + i}
              value={value}
              onChange={onChange}
            />
          ))}
        </>
      )}
    </div>
  )
}

// ── Month grid (helper) ──────────────────────────────────────────────
//
// 12 buttons in a 4x3 grid. Used by the Month tier and the header of
// the Month+Day tier in <DateCarousel>.
function MonthGrid({ value, onChange, priorValue = null, priorAccent = null }) {
  const cal = getActiveCalendar()
  const total = cal.months.short.length
  return (
    <div className="relative grid grid-cols-6 gap-1">
      {cal.months.short.map((name, idx) => {
        const active = value === idx
        const isPrior = priorValue === idx
        return (
          <PickerButton
            key={idx}
            label={name}
            active={active}
            onClick={() => onChange(active ? null : idx)}
            accent={DATE_ACCENT}
            isPrior={isPrior}
            priorAccent={priorAccent}
            priorTooltip={isPrior ? `The previous scene was in ${cal.months.long[idx]}.` : null}
          />
        )
      })}
      <CycleArrow
        priorIdx={priorValue}
        currentIdx={value}
        totalCount={total}
        gridCols={6}
        accentColour={priorAccent}
      />
    </div>
  )
}

// ── Day-of-month grid ────────────────────────────────────────────────
//
// 10-column grid of numbered cells, 1..N where N is the month's day
// count. Ten columns — the cleanest "non-week" grouping because
// humans already count in tens, so each row reads as a decade
// (first ten days, the teens, the twenties, then 31). Seven columns
// would imply weekday positions; 10 maps to no calendar convention
// and reads as plain numbers in groups of ten.
//
// Cells fill left-to-right, top-to-bottom. February gets 28 cells
// filled normally and a 29th cell rendered with secondary styling
// (italic, dimmer border) — clicking it pins Feb 29 explicitly,
// the per-scene leap-year assertion.
// Ordinal suffix for a day-of-month: 1st, 2nd, 3rd, 4th ... 21st,
// 22nd ... 31st. Used in the prior-spot tooltip ("the 6th") so the
// hover reads as natural English.
function _ordinal(n) {
  const mod100 = n % 100
  if (mod100 >= 11 && mod100 <= 13) return `${n}th`
  const mod10 = n % 10
  if (mod10 === 1) return `${n}st`
  if (mod10 === 2) return `${n}nd`
  if (mod10 === 3) return `${n}rd`
  return `${n}th`
}

function DayGrid({ monthIdx, value, onChange, priorValue = null, priorAccent = null }) {
  // When no month is pinned, fall back to the maximum day-count
  // across all months in the active calendar (31 for Gregorian).
  // This lets the writer pin a specific day-of-month independently
  // of choosing a month.
  const isFeb = monthIdx != null && monthIdx === februaryIndex()
  const baseDays = monthIdx != null ? daysInMonth(monthIdx, false) : 31
  const leapDays = monthIdx != null ? daysInMonth(monthIdx, true)  : 31
  const cells = []
  for (let d = 1; d <= leapDays; d++) {
    const isLeapDay = isFeb && d > baseDays
    const active = value === d
    const showPriorRing = priorValue === d && priorAccent
    cells.push(
      <button
        key={d}
        type="button"
        onClick={() => onChange(active ? null : d)}
        className={`text-xs font-medium rounded-md w-7 h-7 transition-colors select-none ${
          active
            ? 'text-zinc-50'
            : isLeapDay
              ? 'text-zinc-500 hover:text-zinc-300 italic'
              : 'text-zinc-300 hover:text-zinc-100 hover:bg-zinc-800'
        }`}
        style={{
          backgroundColor: active ? DATE_ACCENT : 'transparent',
          border: `1px solid ${active ? DATE_ACCENT : isLeapDay ? '#27272a' : '#3f3f46'}`,
          outline: showPriorRing ? `1.5px dashed ${priorAccent}` : 'none',
          outlineOffset: showPriorRing ? '2px' : 0,
        }}
        title={
          [
            showPriorRing ? `The previous scene was on the ${_ordinal(d)}.` : null,
            isLeapDay ? 'Leap day: pick to assert Feb 29 for this scene.' : null,
          ].filter(Boolean).join('\n') || undefined
        }
      >
        {d}
      </button>
    )
  }
  // Two rows always: 15 columns for ≤30-day months (and the no-month
  // fallback rendered at 31 cells… wait, no — see below). When the
  // total day count is 31, use 16 columns so all 31 fit in two rows
  // (16 + 15) instead of spilling to a lonely third row of 1.
  const cols = leapDays > 30 ? 16 : 15
  // Day-of-month is 1-indexed in the data model; convert to 0-indexed
  // for the cycle arrow's grid math (cell 0 = day 1, cell N-1 = day N).
  const priorIdx0 = priorValue == null ? null
    : (priorValue >= 1 && priorValue <= leapDays) ? priorValue - 1 : null
  const valueIdx0 = value == null ? null
    : (value >= 1 && value <= leapDays) ? value - 1 : null
  return (
    <div
      className="relative grid gap-1"
      style={{ gridTemplateColumns: `repeat(${cols}, minmax(0, 1fr))` }}
    >
      {cells}
      <CycleArrow
        priorIdx={priorIdx0}
        currentIdx={valueIdx0}
        totalCount={leapDays}
        gridCols={cols}
        accentColour={priorAccent}
      />
    </div>
  )
}

// ── DateCarousel — three independent latches ────────────────────────
//
// Three independent toggle latches: Weekday / Month / Specific Day.
// Each latch reveals its picker when enabled. Weekday is enabled by
// default; Month and Specific Day are disabled. Latches are
// independent — no tier rotation. The writer can pin any combination
// (weekday only, month only, weekday + day-of-month without a month,
// etc.); no slot blocks any other.
//
// State shape:
//   {
//     enabled: { weekday: bool, month: bool, day: bool },
//     values:  { weekday: 0..6 | null, monthIdx: 0..11 | null, day: 1..31 | null },
//   }
//
// When the day picker is enabled but no month is pinned, the day
// grid renders the maximum day-count across all months (31 for
// Gregorian) — the writer can still pin "the 14th" without
// committing to a month. February's 29th still gets the leap-day
// secondary styling, but only when February IS the pinned month.
// Single labelled toggle row — re-uses the existing iOS-style
// ToggleInput primitive so the date latches feel the same as
// every other toggle in the program.
function DateLatchToggle({ enabled, onToggle, label }) {
  return (
    <div className="flex items-center gap-2">
      <ToggleInput
        value={enabled}
        onCommit={onToggle}
        title={`${enabled ? 'Disable' : 'Enable'} ${label.toLowerCase()}`}
      />
      <span className="text-xs text-zinc-300 select-none">{label}</span>
    </div>
  )
}

export function DateCarousel({ state, onChange, weekStart = 'sunday', priorValues = null, priorAccent = null }) {
  const enabled = state?.enabled ?? { weekday: true, month: false, day: false }
  const values  = state?.values  ?? { weekday: null, monthIdx: null, day: null }
  // Prior pinned values from the immediate prior POV-chain scene.
  // null on each axis means the prior didn't pin that field — the
  // dashed "you-are-here-ish" indicator only renders for axes the
  // prior actually carries data on.
  const pv = priorValues ?? {}
  const priorWd  = (typeof pv.weekday === 'number') ? pv.weekday : null
  const priorMon = (typeof pv.monthIdx === 'number') ? pv.monthIdx : null
  const priorDay = (typeof pv.day === 'number') ? pv.day : null

  const setEnabled = (key, val) => {
    onChange({ enabled: { ...enabled, [key]: val }, values })
  }
  const setValue = (key, val) => {
    onChange({ enabled, values: { ...values, [key]: val } })
  }
  const setMonth = (nextMonthIdx) => {
    // When the month changes, clear the day if it's now out of range
    // for the new month (e.g. day=30 then switch to Feb).
    let nextDay = values.day
    if (nextMonthIdx != null && nextDay != null) {
      const max = daysInMonth(nextMonthIdx, true)
      if (nextDay > max) nextDay = null
    }
    onChange({ enabled, values: { ...values, monthIdx: nextMonthIdx, day: nextDay } })
  }

  // Reserved height covers the worst case — all three latches enabled
  // with the largest pickers (weekday row + 2-row month grid + 2-row
  // day grid + the toggle row + gaps). Keeps the surrounding modal
  // layout stable as latches turn on / off.
  return (
    <div className="flex flex-col gap-3" style={{ minHeight: 240 }} data-help-region="scene-time:date">
      <div className="flex justify-center flex-wrap gap-x-6 gap-y-2">
        <DateLatchToggle enabled={enabled.weekday} onToggle={(v) => setEnabled('weekday', v)} label="Weekday" />
        <DateLatchToggle enabled={enabled.month}   onToggle={(v) => setEnabled('month',   v)} label="Month" />
        <DateLatchToggle enabled={enabled.day}     onToggle={(v) => setEnabled('day',     v)} label="Specific Day" />
      </div>

      {enabled.weekday && (
        <WeekdayRow
          value={values.weekday}
          onChange={(v) => setValue('weekday', v)}
          weekStart={weekStart}
          priorValue={priorWd}
          priorAccent={priorAccent}
        />
      )}

      {enabled.month && (
        <MonthGrid
          value={values.monthIdx}
          onChange={setMonth}
          priorValue={priorMon}
          priorAccent={priorAccent}
        />
      )}

      {enabled.day && (
        <DayGrid
          monthIdx={values.monthIdx}
          value={values.day}
          onChange={(v) => setValue('day', v)}
          priorValue={priorDay}
          priorAccent={priorAccent}
        />
      )}
    </div>
  )
}
